/* ==UserStyle==
@name           Eli Pagedoll
@namespace      userstyles.world/elias
@version        1.1.0
@description    Black Sapphire Cookie pagedoll
@author         cybrvmp
==/UserStyle== */

/* animation must be OUTSIDE */
@keyframes pagedoll-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-15px); }
}

/* media must be OUTSIDE */
@media (max-width: 600px) {
  html::after {
    display: none !important;
  }
}

/* main pagedoll */
@-moz-document url-prefix("https://"), url-prefix("http://") {
html::after {
    content: "";
    display: block;

    background-image: url("https://static.wikia.nocookie.net/cookierunkingdom/images/0/0a/Black_sapphire_gacha_animation.gif/revision/latest/scale-to-width-down/201?cb=20250212093418");
    background-size: contain;
    background-repeat: no-repeat;

    position: fixed;
    bottom: 20px;
    right: 20px;
    width: 200px;
    height: 200px;

    z-index: 2147483647;
    pointer-events: none;

    animation: pagedoll-float 3s ease-in-out infinite;
  }
}
